package org.apache.commons.math.geometry.euclidean.threed;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for Rotation.getAngle() to maximize branch and line coverage.
 */
public class Rotation_getAngle_TriageGen2Test {

    private static final double DELTA = 1e-12;

    /**
     * Tests the first branch: (q0 < -0.1) || (q0 > 0.1)
     * Formula: 2 * asin(sqrt(q1^2 + q2^2 + q3^2))
     */
    @Test
    public void testGetAngle_Branch1_PositiveQ0() {
        // q0 = 0.5 ( > 0.1)
        // q1=0.5, q2=0.5, q3=0.5 -> sqrt(0.25+0.25+0.25) = sqrt(0.75)
        double q0 = 0.5;
        double q1 = 0.5;
        double q2 = 0.5;
        double q3 = 0.5;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.asin(FastMath.sqrt(q1 * q1 + q2 * q2 + q3 * q3));
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    @Test
    public void testGetAngle_Branch1_NegativeQ0() {
        // q0 = -0.5 ( < -0.1)
        double q0 = -0.5;
        double q1 = 0.1;
        double q2 = 0.1;
        double q3 = 0.1;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.asin(FastMath.sqrt(q1 * q1 + q2 * q2 + q3 * q3));
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    /**
     * Tests the second branch: else if (q0 < 0)
     * This occurs when -0.1 <= q0 < 0
     * Formula: 2 * acos(-q0)
     */
    @Test
    public void testGetAngle_Branch2_NegativeQ0() {
        // q0 = -0.05 (between -0.1 and 0)
        double q0 = -0.05;
        double q1 = 0.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(-q0);
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    /**
     * Tests the third branch (default return): 
     * This occurs when 0 <= q0 <= 0.1
     * Formula: 2 * acos(q0)
     */
    @Test
    public void testGetAngle_Branch3_PositiveQ0() {
        // q0 = 0.05 (between 0 and 0.1)
        double q0 = 0.05;
        double q1 = 0.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(q0);
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    @Test
    public void testGetAngle_Branch3_ZeroQ0() {
        // q0 = 0.0 (exactly 0)
        double q0 = 0.0;
        double q1 = 0.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(q0);
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    @Test
    public void testGetAngle_Branch3_BoundaryQ0() {
        // q0 = 0.1 (exactly 0.1)
        double q0 = 0.1;
        double q1 = 0.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(q0);
        assertEquals(expected, rotation.getAngle(), DELTA);
    }

    @Test
    public void testGetAngle_Branch2_BoundaryQ0() {
        // q0 = -0.1 (exactly -0.1)
        // Note: the condition is (q0 < -0.1), so -0.1 should fall into the 'else if'
        double q0 = -0.1;
        double q1 = 0.0;
        double q2 = 0.0;
        double q3 = 0.0;
        Rotation rotation = new Rotation(q0, q1, q2, q3, true);

        double expected = 2 * FastMath.acos(-q0);
        assertEquals(expected, rotation.getAngle(), DELTA);
    }
}
